-- | Haskell code generator (M2T) - the kUML "generate" target retargeted to
-- Haskell, mirroring kUML's @KumlCodeGenerator@ conventions (a provenance
-- header, one cohesive module, sanitized names) but adapted to Haskell.
--
-- UML class-diagram -> Haskell mapping (analogous to kuml-gen-kotlin):
--   UmlClass        -> `data` record (fields = attributes)
--   UmlInterface    -> typeclass  (methods = operations, instance var `a`)
--   UmlEnumeration  -> sum type   (one nullary constructor per literal)
--   operation (on a class) -> a top-level function stub (record is first arg)
--   realization (Class ..|> Iface) -> `instance Iface Class where ...` (stubs)
--   generalization / association / dependency -> documented as comments
--     (Kotlin uses subtyping, which Haskell lacks; kUML's Java/SQL generators
--     also drop these, so there is no target to copy - comments are honest).
--
-- Design goal: the emitted module MUST COMPILE. Unknown attribute/parameter
-- types become `type T = String` stubs; every function/method body is
-- `error "..."` (polymorphic, so it typechecks at any arity); every generated
-- name is prefixed for module-global uniqueness (Haskell 2010 has no
-- DuplicateRecordFields, and typeclass methods / constructors share one
-- namespace).
--
-- Prelude + Data.Char only; no Either-monad, no higher-order threading - same
-- JHC-safety constraints as the rest of the port.
module Kuml.Gen.Haskell (generateHaskell) where

import Kuml.Types
import Data.Char (toUpper, toLower, isAlpha, isAlphaNum)

-- | Generate a single self-contained Haskell module from a diagram.
-- @mmod@ overrides the module name (default: derived from the diagram name).
generateHaskell :: Maybe String -> Diagram -> String
generateHaskell mmod d =
  let cls  = diagClasses d
      rels = diagRels d
      modName = sanitizeModule (maybe (diagName d) id mmod)
  in concat
       [ headerComment
       , "module " ++ modName ++ " where\n\n"
       , sectionExternals cls
       , sectionEnums cls
       , sectionInterfaces cls
       , sectionData cls
       , sectionClassOps cls
       , sectionInstances cls rels
       , sectionRelComments rels
       ]

headerComment :: String
headerComment =
  "-- Generated by kuml-gen-haskell -- do not edit manually.\n"
  ++ "-- Target: Haskell (records + typeclasses). Bodies are `error` stubs to fill in.\n\n"

-- -- classifier predicates ----------------------------------------------------

isClassKind :: Classifier -> Bool
isClassKind c = case clsKind c of { KClass _ -> True; _ -> False }

isInterfaceKind :: Classifier -> Bool
isInterfaceKind c = case clsKind c of { KInterface -> True; _ -> False }

isEnumKind :: Classifier -> Bool
isEnumKind c = case clsKind c of { KEnum -> True; _ -> False }

isAbstract :: Classifier -> Bool
isAbstract c = case clsKind c of { KClass True -> True; _ -> False }

-- -- type mapping --------------------------------------------------------------

-- Prelude type for a known primitive name (case variants included), else Nothing.
builtinType :: String -> Maybe String
builtinType t = case t of
  "String"  -> Just "String"; "string" -> Just "String"; "str" -> Just "String"; "Text" -> Just "String"
  "Int"     -> Just "Int";     "int"    -> Just "Int"
  "Integer" -> Just "Integer"; "integer"-> Just "Integer"
  "Long"    -> Just "Integer"; "long"   -> Just "Integer"
  "Float"   -> Just "Float";   "float"  -> Just "Float"
  "Double"  -> Just "Double";  "double" -> Just "Double"
  "Boolean" -> Just "Bool";    "boolean"-> Just "Bool"; "bool" -> Just "Bool"; "Bool" -> Just "Bool"
  "Char"    -> Just "Char";    "char"   -> Just "Char"
  "Byte"    -> Just "Int";     "Short"  -> Just "Int"
  "Unit"    -> Just "()";      "void"   -> Just "()"; "Void" -> Just "()"; "()" -> Just "()"
  _         -> Nothing

-- Consume 'builtinType' via case, never via `== Nothing` (JHC 0.8.2 mis-evaluates
-- Eq on Maybe here, wrongly classing builtins/defined names as external).
isBuiltin :: String -> Bool
isBuiltin t = case builtinType t of { Just _ -> True; Nothing -> False }

-- Explicit membership (avoid any comprehension/elem desugaring surprises).
hasName :: String -> [String] -> Bool
hasName _ [] = False
hasName x (y:ys) = if x == y then True else hasName x ys

-- Render a model type name as a Haskell type. Builtins map through; a name that
-- is a defined interface can't be a plain field type (it's a class), so it
-- degrades to String; everything else (defined data type OR external stub) uses
-- its sanitized constructor name.
hsType :: [Classifier] -> String -> String
hsType cls t
  | null t                = "String"
  | otherwise =
      case builtinType t of
        Just b  -> b
        Nothing -> if hasName t ifaceNames then "String" else sanitizeCon t
  where ifaceNames = [clsName c | c <- cls, isInterfaceKind c]

-- -- external stub aliases ------------------------------------------------------

referencedTypes :: Classifier -> [String]
referencedTypes c =
  [ attrType a | a <- clsAttrs c, not (null (attrType a)) ]
  ++ concatMap opTypes (clsOps c)
  where
    opTypes o = [ paramType p | p <- opParams o, not (null (paramType p)) ]
             ++ maybe [] (\r -> [r]) (opReturn o)

sectionExternals :: [Classifier] -> String
sectionExternals cls =
  if null exts then ""
  else "-- External / unmodeled types (stubbed as String so the module is self-contained).\n"
       ++ concatMap (\t -> "type " ++ sanitizeCon t ++ " = String\n") exts ++ "\n"
  where
    defined = [clsName c | c <- cls]
    exts    = uniqueStrs (keepExternal (concatMap referencedTypes cls))
    keepExternal [] = []
    keepExternal (t:ts)
      | not (null t) && not (isBuiltin t) && not (hasName t defined) = t : keepExternal ts
      | otherwise                                                    = keepExternal ts

-- -- enums ----------------------------------------------------------------------

sectionEnums :: [Classifier] -> String
sectionEnums cls = concatMap emitEnum [c | c <- cls, isEnumKind c]

emitEnum :: Classifier -> String
emitEnum c =
  let n     = sanitizeCon (clsName c)
      lits  = clsLits c
      ctors = if null lits
                then [n ++ "_Empty"]
                else map (\l -> sanitizeCon (clsName c ++ "_" ++ l)) lits
  in "data " ++ n ++ " = " ++ sepBy " | " ctors
       ++ "\n  deriving (Eq, Show, Enum, Bounded)\n\n"

-- -- interfaces -> typeclasses ------------------------------------------------

sectionInterfaces :: [Classifier] -> String
sectionInterfaces cls = concatMap (emitInterface cls) [c | c <- cls, isInterfaceKind c]

emitInterface :: [Classifier] -> Classifier -> String
emitInterface cls c =
  let n   = sanitizeCon (clsName c)
      ops = clsOps c
      sig o = "  " ++ methodName (clsName c) (opName o) ++ " :: "
                ++ sepBy " -> " ("a" : map (paramHsType cls) (opParams o) ++ [retHsType cls o]) ++ "\n"
  in if null ops
       then "class " ++ n ++ " a\n\n"
       else "class " ++ n ++ " a where\n" ++ concatMap sig ops ++ "\n"

-- -- classes -> data records ------------------------------------------------

sectionData :: [Classifier] -> String
sectionData cls = concatMap (emitData cls) [c | c <- cls, isClassKind c]

emitData :: [Classifier] -> Classifier -> String
emitData cls c =
  let n     = sanitizeCon (clsName c)
      attrs = clsAttrs c
      cmt   = if isAbstract c then "-- | abstract (UML)\n" else ""
      decl  = if null attrs
                then "data " ++ n ++ " = " ++ n ++ "\n  deriving (Eq, Show)\n\n"
                else "data " ++ n ++ " = " ++ n ++ "\n"
                       ++ fieldBlock [ fieldName (clsName c) (attrName a) ++ " :: " ++ hsType cls (attrType a)
                                     | a <- attrs ]
                       ++ "  deriving (Eq, Show)\n\n"
  in cmt ++ decl

fieldBlock :: [String] -> String
fieldBlock [] = ""
fieldBlock (x:xs) =
  "  { " ++ x ++ "\n" ++ concatMap (\f -> "  , " ++ f ++ "\n") xs ++ "  }\n"

-- -- class operations -> top-level function stubs -----------------------------

sectionClassOps :: [Classifier] -> String
sectionClassOps cls = concatMap (emitClassOps cls) [c | c <- cls, isClassKind c]

emitClassOps :: [Classifier] -> Classifier -> String
emitClassOps cls c = concatMap (emitOp cls c) (clsOps c)

emitOp :: [Classifier] -> Classifier -> Operation -> String
emitOp cls c o =
  let n   = sanitizeCon (clsName c)
      fn  = opFuncName (clsName c) (opName o)
      sig = fn ++ " :: " ++ sepBy " -> " (n : map (paramHsType cls) (opParams o) ++ [retHsType cls o])
      def = fn ++ " = error " ++ show ("kuml-gen-haskell: " ++ clsName c ++ "." ++ opName o ++ " not implemented")
  in "-- | operation " ++ clsName c ++ "." ++ opName o ++ "\n" ++ sig ++ "\n" ++ def ++ "\n\n"

paramHsType :: [Classifier] -> Param -> String
paramHsType cls p = hsType cls (paramType p)

retHsType :: [Classifier] -> Operation -> String
retHsType cls o = maybe "()" (hsType cls) (opReturn o)

-- -- realization -> instance stubs --------------------------------------------

sectionInstances :: [Classifier] -> [Relationship] -> String
sectionInstances cls rels =
  concatMap (emitInstance cls) [r | r <- rels, relKind r == RRealization]

emitInstance :: [Classifier] -> Relationship -> String
emitInstance cls r =
  case (findBy cls (relFrom r), findBy cls (relTo r)) of
    (Just impl, Just iface)
      | isClassKind impl && isInterfaceKind iface ->
          let n   = sanitizeCon (relFrom r)
              iN  = sanitizeCon (relTo r)
              ops = clsOps iface
              stub o = "  " ++ methodName (relTo r) (opName o) ++ " = error "
                         ++ show ("kuml-gen-haskell: " ++ relFrom r ++ " realizes " ++ relTo r
                                   ++ "." ++ opName o ++ " -- not implemented") ++ "\n"
          in if null ops
               then "instance " ++ iN ++ " " ++ n ++ " where\n\n"
               else "instance " ++ iN ++ " " ++ n ++ " where\n" ++ concatMap stub ops ++ "\n"
    _ -> ""

findBy :: [Classifier] -> String -> Maybe Classifier
findBy cls name = case [c | c <- cls, clsName c == name] of
  (c:_) -> Just c
  []    -> Nothing

-- -- generalizations / associations / dependencies -> comments ----------------

sectionRelComments :: [Relationship] -> String
sectionRelComments rels =
  block "Generalizations (UML is-a; Haskell has no inheritance)"
        [r | r <- rels, relKind r == RGeneralization]
        (\r -> relFrom r ++ " --|> " ++ relTo r)
  ++ block "Associations"
        [r | r <- rels, isAssocRel (relKind r)]
        (\r -> relFrom r ++ " " ++ arrowOf (relKind r) ++ " " ++ relTo r)
  ++ block "Dependencies"
        [r | r <- rels, relKind r == RDependency]
        (\r -> relFrom r ++ " ..> " ++ relTo r)
  where
    block _    []    _   = ""
    block name items fmt =
      "-- " ++ name ++ ":\n" ++ concatMap (\r -> "--   " ++ fmt r ++ "\n") items ++ "\n"

isAssocRel :: RelKind -> Bool
isAssocRel k = k == RAssociation || k == RComposition || k == RAggregation

arrowOf :: RelKind -> String
arrowOf RComposition = "*--"
arrowOf RAggregation = "o--"
arrowOf _            = "--"

-- -- name sanitization / helpers ----------------------------------------------

-- A valid Haskell type/data-constructor name: keep alphanumerics + '_', ensure
-- the first character is an uppercase letter.
sanitizeCon :: String -> String
sanitizeCon s =
  case map keep s of
    []       -> "T_"
    (x:xs)   -> if isAlpha x then toUpper x : xs else 'T' : x : xs
  where keep ch = if isAlphaNum ch || ch == '_' then ch else '_'

-- A valid Haskell identifier (lowercase-initial), for fields/functions/methods.
sanitizeVar :: String -> String
sanitizeVar s =
  case map keep s of
    []     -> "f_"
    (x:xs) -> if isAlpha x then toLower x : xs else 'f' : x : xs
  where keep ch = if isAlphaNum ch || ch == '_' then ch else '_'

-- Record field: <lowerOwner><CapAttr> (unique across the module).
fieldName :: String -> String -> String
fieldName owner attr = sanitizeVar (lowerHead (alnum owner) ++ capHead (alnum attr))

-- Typeclass method: <lowerIface><CapOp>.
methodName :: String -> String -> String
methodName owner op = sanitizeVar (lowerHead (alnum owner) ++ capHead (alnum op))

-- Class-operation function: <lowerClass><CapOp>.
opFuncName :: String -> String -> String
opFuncName owner op = sanitizeVar (lowerHead (alnum owner) ++ capHead (alnum op))

-- Module name: PascalCase the alphanumeric words of the diagram name.
sanitizeModule :: String -> String
sanitizeModule s =
  case concatMap capHead (words (map spaceNonAlnum s)) of
    []     -> "Model"
    (x:xs) -> if isAlpha x then toUpper x : xs else 'M' : x : xs
  where spaceNonAlnum ch = if isAlphaNum ch then ch else ' '

alnum :: String -> String
alnum = filter (\ch -> isAlphaNum ch || ch == '_')

lowerHead :: String -> String
lowerHead []     = []
lowerHead (x:xs) = toLower x : xs

capHead :: String -> String
capHead []     = []
capHead (x:xs) = toUpper x : xs

sepBy :: String -> [String] -> String
sepBy _   []     = ""
sepBy _   [x]    = x
sepBy sep (x:xs) = x ++ sep ++ sepBy sep xs

uniqueStrs :: [String] -> [String]
uniqueStrs = go []
  where
    go _    []     = []
    go seen (y:ys) = if y `elem` seen then go seen ys else y : go (y : seen) ys
